public class LinearFloorCeil {
    public int[] floorCeil(int[] arr, int x) {
        int floor = -1, ceil = -1;
        for (int v : arr) {
            if (v <= x) floor = v;
            if (v >= x && ceil == -1) ceil = v;
        }
        return new int[]{floor, ceil};
    }

    public static void main(String[] args) {
        int[] r = new LinearFloorCeil().floorCeil(new int[]{1, 2, 8, 10, 12, 19}, 5);
        System.out.println(r[0] + " " + r[1]);
    }
}

