def floor_ceil(arr: list[int], x: int) -> tuple[int, int]:
    floor = ceil = -1
    for v in arr:
        if v <= x:
            floor = v
        if v >= x and ceil == -1:
            ceil = v
    return floor, ceil


if __name__ == "__main__":
    print(floor_ceil([1, 2, 8, 10, 12, 19], 5))

