public class BinaryFloorCeil {
    public int floor(int[] arr, int x) {
        int lo = 0, hi = arr.length - 1, ans = -1;
        while (lo <= hi) {
            int mid = lo + (hi - lo) / 2;
            if (arr[mid] <= x) {
                ans = arr[mid];   // candidate, then try for a larger valid value
                lo = mid + 1;
            } else {
                hi = mid - 1;
            }
        }
        return ans;
    }

    public int ceil(int[] arr, int x) {
        int lo = 0, hi = arr.length - 1, ans = -1;
        while (lo <= hi) {
            int mid = lo + (hi - lo) / 2;
            if (arr[mid] >= x) {
                ans = arr[mid];   // candidate, then try for a smaller valid value
                hi = mid - 1;
            } else {
                lo = mid + 1;
            }
        }
        return ans;
    }

    public static void main(String[] args) {
        BinaryFloorCeil b = new BinaryFloorCeil();
        int[] a = {1, 2, 8, 10, 12, 19};
        System.out.println(b.floor(a, 5) + " " + b.ceil(a, 5));
    }
}

