def floor(arr: list[int], x: int) -> int:
    lo, hi, ans = 0, len(arr) - 1, -1
    while lo <= hi:
        mid = lo + (hi - lo) // 2
        if arr[mid] <= x:
            ans = arr[mid]      # candidate, then search right for a larger valid value
            lo = mid + 1
        else:
            hi = mid - 1
    return ans


def ceil(arr: list[int], x: int) -> int:
    lo, hi, ans = 0, len(arr) - 1, -1
    while lo <= hi:
        mid = lo + (hi - lo) // 2
        if arr[mid] >= x:
            ans = arr[mid]      # candidate, then search left for a smaller valid value
            hi = mid - 1
        else:
            lo = mid + 1
    return ans


if __name__ == "__main__":
    a = [1, 2, 8, 10, 12, 19]
    print(floor(a, 5), ceil(a, 5))

